<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/catalog.php'; require_auth();
$user=current_user(); $status=$_GET['status']??''; $subcategory=$_GET['subcategory']??''; $search=trim($_GET['search']??''); $options=product_subcategories();
$sql='SELECT code,name,category,subcategory,size,condition_grade,price,entry_date,origin,status FROM products WHERE user_id=?'; $values=[$user['id']];
if(in_array($status,['Disponível','Vendido','Reservado'],true)){$sql.=' AND status=?';$values[]=$status;} if(isset($options[$subcategory])){$sql.=' AND subcategory=?';$values[]=$options[$subcategory];} if($search){$sql.=' AND (name LIKE ? OR code LIKE ?)';$values[]='%'.$search.'%';$values[]='%'.$search.'%';} $sql.=' ORDER BY entry_date DESC,id DESC'; $query=db()->prepare($sql);$query->execute($values);$products=$query->fetchAll();
if(isset($_GET['download'])){header('Content-Type:text/csv; charset=utf-8');header('Content-Disposition:attachment; filename=relatorio-estoque.csv');$out=fopen('php://output','w');fputcsv($out,['Código','Peça','Categoria','Subcategoria','Tamanho','Condição','Preço','Entrada','Origem','Status'],';');foreach($products as $product)fputcsv($out,$product,';');fclose($out);exit;}$totalValue=array_sum(array_map(static fn(array $product):float=>(float)$product['price'],$products));$pageTitle='Relatório';require __DIR__.'/partials/header.php';
?><div class="d-flex justify-content-between align-items-center mb-4"><div><div class="eyebrow">Visão do acervo</div><h1 class="page-title h3 mb-0">Relatório de estoque</h1></div><a class="btn btn-primary" href="report.php?download=1&amp;status=<?=urlencode($status)?>&amp;subcategory=<?=urlencode($subcategory)?>&amp;search=<?=urlencode($search)?>"><i data-lucide="download"></i> Baixar CSV</a></div><form class="panel mb-3" method="get"><div class="row g-3 align-items-end"><div class="col-md-4"><label class="form-label">Buscar peça ou código</label><input class="form-control" name="search" value="<?=e($search)?>"></div><div class="col-md-3"><label class="form-label">Status</label><select class="form-select" name="status"><option value="">Todos</option><?php foreach(['Disponível','Vendido','Reservado'] as $option): ?><option <?= $status===$option?'selected':'' ?>><?=$option?></option><?php endforeach; ?></select></div><div class="col-md-3"><label class="form-label">Subcategoria</label><select class="form-select" name="subcategory"><option value="">Todas</option><?php foreach($options as $code=>$name): ?><option value="<?=$code?>" <?=$subcategory===$code?'selected':'' ?>><?=e($name)?> (<?=$code?>)</option><?php endforeach; ?></select></div><div class="col-md-2"><button class="btn btn-outline-secondary w-100"><i data-lucide="filter"></i> Aplicar</button></div></div></form><div class="row g-3 mb-3"><div class="col-md-6"><div class="stat-card"><div class="text-muted small">Itens no resultado</div><div class="stat-number"><?=count($products)?></div></div></div><div class="col-md-6"><div class="stat-card"><div class="text-muted small">Valor total listado</div><div class="stat-number">R$ <?=number_format($totalValue,2,',','.')?></div></div></div></div><div class="panel p-0 overflow-hidden"><div class="table-responsive"><table class="table mb-0 align-middle"><thead><tr><th>Código / peça</th><th>Categoria</th><th>Subcategoria</th><th>Preço</th><th>Origem</th><th>Status</th></tr></thead><tbody><?php foreach($products as $product): ?><tr><td><strong><?=e($product['code'])?></strong><div><?=e($product['name'])?></div></td><td><?=e($product['category'])?></td><td><?=e($product['subcategory'])?></td><td>R$ <?=number_format((float)$product['price'],2,',','.')?></td><td><?=e($product['origin'])?></td><td><span class="status-badge <?=e(status_class($product['status']))?>"><?=e($product['status'])?></span></td></tr><?php endforeach; if(!$products): ?><tr><td colspan="6" class="empty">Nenhuma peça corresponde aos filtros.</td></tr><?php endif; ?></tbody></table></div></div><?php require __DIR__.'/partials/footer.php'; ?>
